import torch
import torch.nn.functional as F

def run(x1, x2, x1scale, x2scale, bias, fused_op_type, out_dtype, transpose_x1=False, transpose_x2=False):
    if transpose_x1:
        x1 = x1.transpose(-2, -1)
    if transpose_x2:
        x2 = x2.transpose(-2, -1)
    temp = torch.matmul(x1.to(torch.float32), x2.to(torch.float32))
    x2scale_f = x2scale.to(torch.float32)
    x1scale_f = x1scale.unsqueeze(-1).to(torch.float32)
    if bias is None:
        out = temp * x2scale_f * x1scale_f
    elif bias.dtype == torch.int32:
        out = (temp + bias.to(torch.float32)) * x2scale_f * x1scale_f
    else:
        out = temp * x2scale_f * x1scale_f + bias.to(torch.float32)
    if fused_op_type == "gelu_erf":
        out = F.gelu(out, approximate='none')
    elif fused_op_type == "gelu_tanh":
        out = F.gelu(out, approximate='tanh')
    dtype_map = {"float16": torch.float16, "bfloat16": torch.bfloat16, "float32": torch.float32, "int32": torch.int32, "int8": torch.int8}
    target_dtype = dtype_map.get(out_dtype, torch.float16) if isinstance(out_dtype, str) else out_dtype
    return out.to(target_dtype)
